package stream

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// ValidateBuild is the read-only integrity check over one published build
// (D4, the healing mechanism's shared half): for the build directory
// Root/<itemID>/<nonce> it parses every published .m3u8 — the root playlist
// (a rendition build's master included) and every variant playlist beside or
// beneath it — and asserts that every referenced URI (each segment line and
// each EXT-X-MAP URI="…") resolves to an existing file relative to that
// playlist's OWN directory, exactly the resolution hls.js performs
// client-side; the strict /media join then either serves the file or the
// build was lying. When a playlist carries ENDLIST (a complete build) the
// union of referenced segments must additionally EQUAL every seg-*.m4s
// published under the build directory (filename set-equality, full
// build-relative paths — a complete playlist that omits published segments
// strands content and fakes the duration); partial builds are exempt from the
// coverage half by design, since their playlists legitimately lag the disk
// while growing. A missing build directory, an unreadable playlist, or no
// playlist at all is invalid. Read-only: no media parsing, no state writes,
// a few small text files plus stats per build — cheap enough for the
// descriptor path (D5) and the integrity sweep alike. Nil means the build
// answers everything the player will ask of it.
func (s *Service) ValidateBuild(itemID, nonce string) error {
	dir, err := s.buildDir(itemID, nonce)
	if err != nil {
		return err
	}
	switch fi, err := os.Stat(dir); {
	case err != nil:
		return fmt.Errorf("stream: validate %s/%s: build dir: %w", itemID, nonce, err)
	case !fi.IsDir():
		return fmt.Errorf("stream: validate %s/%s: build dir is not a directory", itemID, nonce)
	}

	// One walk collects both sides of the coverage half: every playlist to
	// parse and every published segment (full build-relative slash paths).
	var playlists, published []string
	walkErr := filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(dir, p)
		if err != nil {
			return err
		}
		name := d.Name()
		switch {
		case isSegmentName(name):
			published = append(published, filepath.ToSlash(rel))
		case strings.HasSuffix(name, ".m3u8"):
			playlists = append(playlists, p)
		}
		return nil
	})
	if walkErr != nil {
		return fmt.Errorf("stream: validate %s/%s: %w", itemID, nonce, walkErr)
	}
	if len(playlists) == 0 {
		return fmt.Errorf("stream: validate %s/%s: no playlist published", itemID, nonce)
	}

	complete := false
	referenced := map[string]bool{}
	for _, pl := range playlists {
		refs, endlist, err := parsePlaylist(pl)
		if err != nil {
			return fmt.Errorf("stream: validate %s/%s: %w", itemID, nonce, err)
		}
		complete = complete || endlist
		base := filepath.Dir(pl)
		for _, ref := range refs {
			resolved := filepath.Join(base, ref)
			rel, err := filepath.Rel(dir, resolved)
			if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
				return fmt.Errorf("stream: validate %s/%s: playlist %s references %q outside the build (unservable)", itemID, nonce, filepath.Base(pl), ref)
			}
			if _, err := os.Stat(resolved); err != nil {
				return fmt.Errorf("stream: validate %s/%s: playlist %s references %q: not found relative to the playlist dir (player 404)", itemID, nonce, filepath.Base(pl), ref)
			}
			if seg := filepath.ToSlash(rel); isSegmentName(filepath.Base(seg)) {
				referenced[seg] = true // reachable + inside the build: covered
			}
		}
	}
	if !complete {
		return nil // partial build: the coverage half is exempt by design
	}
	var stranded []string
	for _, seg := range published {
		if !referenced[seg] {
			stranded = append(stranded, seg)
		}
	}
	if len(stranded) > 0 {
		sort.Strings(stranded)
		return fmt.Errorf("stream: validate %s/%s: complete build omits %d published segment(s): %s", itemID, nonce, len(stranded), strings.Join(stranded, ", "))
	}
	return nil
}

// isSegmentName reports whether a file name is one build segment (the
// pack lane's seg-NNNNN.m4s shape) — the only artifacts the coverage half
// counts. Init segments (EXT-X-MAP targets) and playlists never match.
func isSegmentName(name string) bool {
	return strings.HasPrefix(name, "seg-") && strings.HasSuffix(name, ".m4s")
}

// parsePlaylist reads one .m3u8 and returns its referenced URIs in playlist
// order — every non-tag line (a segment or variant-playlist URI) plus every
// EXT-X-MAP URI="…" attribute — and whether the playlist carries ENDLIST
// (the complete-build marker). An unreadable file is an error.
func parsePlaylist(path string) (refs []string, endlist bool, err error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, false, err
	}
	for _, line := range strings.Split(string(b), "\n") {
		line = strings.TrimSpace(line)
		switch {
		case line == "":
		case strings.HasPrefix(line, "#"):
			if strings.HasPrefix(line, "#EXT-X-ENDLIST") {
				endlist = true
			}
			if strings.HasPrefix(line, "#EXT-X-MAP") {
				if uri, ok := uriAttribute(line); ok {
					refs = append(refs, uri)
				}
			}
		default:
			refs = append(refs, line)
		}
	}
	return refs, endlist, nil
}

// uriAttribute extracts the URI="…" attribute value of one HLS tag
// (the EXT-X-MAP init segment). Absent or unterminated → not ok.
func uriAttribute(tag string) (string, bool) {
	const key = `URI="`
	i := strings.Index(tag, key)
	if i < 0 {
		return "", false
	}
	rest := tag[i+len(key):]
	j := strings.Index(rest, `"`)
	if j < 0 {
		return "", false
	}
	return rest[:j], true
}
